import random
target='(((((((((((((((.(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).(((.....))).(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).(((.....))).(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).(((.....))).(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).(((.....))).(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).)))))))))))))))'
n=len(target)
stack=[];pairs=[]
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')': j=stack.pop(); pairs.append((j,i))
pairs.sort()  # by i ascending; j descending within a stem

# group into stems: consecutive i increasing by 1, j decreasing by 1
stems=[];cur=[pairs[0]]
for p in pairs[1:]:
    pi,pj=cur[-1]
    if p[0]==pi+1 and p[1]==pj-1:
        cur.append(p)
    else:
        stems.append(cur); cur=[p]
stems.append(cur)

from collections import Counter
print('stem lens',Counter(len(s) for s in stems), 'nstems',len(stems))
# group by length
by_len={}
for si,s in enumerate(stems):
    by_len.setdefault(len(s),[]).append(si)
for L in sorted(by_len): print('L',L,'n',len(by_len[L]))

comp={'G':'C','C':'G','A':'U','U':'A'}
def distinct_gc(length,count):
    res=set(); att=0
    while len(res)<count and att<200000:
        att+=1
        res.add(''.join(random.choice('GC') for _ in range(length)))
    return list(res)

random.seed(7)
seq=['A']*n
for L,idxs in by_len.items():
    pats=distinct_gc(L,len(idxs))
    # for length 1 (inner 2-bp/3-bp hairpins are single pairs): only 2 distinct (G or C). 
    # Actually length-1 stems are the single closing pairs. They can be all G-C (same) — single pair, 
    # cross-pairing with another single G-C pair is just one G-C bond, weak, ignorable.
    if L==1:
        # assign all G-C
        for si in idxs:
            for (i,j) in stems[si]:
                seq[i]='G'; seq[j]='C'
        continue
    for k,si in enumerate(idxs):
        five=pats[k]
        for pos,(i,j) in enumerate(stems[si]):
            seq[i]=five[pos]; seq[j]=comp[five[pos]]

full=''.join(seq)
print('len',len(full))
bad=[(i,j,full[i],full[j]) for (i,j) in pairs if comp[full[i]]!=full[j]]
print('bad pairs',len(bad))
# verify distinctness per length>1
for L,idxs in by_len.items():
    if L==1: continue
    seen=[''.join(seq[i] for (i,j) in stems[si]) for si in idxs]
    print('L',L,'distinct?',len(set(seen))==len(seen))
print(full)
